import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.C0KMm31j.js";const s="/Nav2ArticlesSite/article-assets/2026-07-27/teb_core_01_band_overview.png",n="/Nav2ArticlesSite/article-assets/2026-07-27/teb_core_02_resize_warmstart.png",l="/Nav2ArticlesSite/article-assets/2026-07-27/teb_core_03_sparse_graph.png",c="/Nav2ArticlesSite/article-assets/2026-07-27/teb_core_04_motion_time_cost.png",d="/Nav2ArticlesSite/article-assets/2026-07-27/teb_core_05_optimization_loop.png",p="/Nav2ArticlesSite/article-assets/2026-07-27/teb_core_06_homotopy_output.png",x=JSON.parse('{"title":"路径会被障碍“拽弯”，时间还会自己收缩：Nav2 TEB 图优化核心拆解","description":"一条普通路径只回答“经过哪里”，却没有回答“什么时候到这里”。没有时间，速度和加速度只能在路径生成后另算；空间绕障与时间可执行性也容易互相打架。","frontmatter":{"title":"路径会被障碍“拽弯”，时间还会自己收缩：Nav2 TEB 图优化核心拆解","description":"一条普通路径只回答“经过哪里”，却没有回答“什么时候到这里”。没有时间，速度和加速度只能在路径生成后另算；空间绕障与时间可执行性也容易互相打架。","date":"2026-07-27","section":"二 · 全局规划与路径搜索","readingTime":13,"source":"2026-07-27/teb_local_planner_core_algorithm.md","status":"published","cover":"/article-assets/2026-07-27/teb_core_01_band_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/teb-local-planner-core-algorithm"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"路径会被障碍“拽弯”，时间还会自己收缩：Nav2 TEB 图优化核心拆解"}],["meta",{"property":"og:description","content":"一条普通路径只回答“经过哪里”，却没有回答“什么时候到这里”。没有时间，速度和加速度只能在路径生成后另算；空间绕障与时间可执行性也容易互相打架。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/teb-local-planner-core-algorithm"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/teb_core_01_band_overview.png"}],["meta",{"property":"article:published_time","content":"2026-07-27"}],["meta",{"name":"twitter:title","content":"路径会被障碍“拽弯”，时间还会自己收缩：Nav2 TEB 图优化核心拆解"}],["meta",{"name":"twitter:description","content":"一条普通路径只回答“经过哪里”，却没有回答“什么时候到这里”。没有时间，速度和加速度只能在路径生成后另算；空间绕障与时间可执行性也容易互相打架。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-27/teb_core_01_band_overview.png"}]],"prev":{"text":"A* 为什么非要一格一格拐？Nav2 Theta* 用一条视线把路径拉直","link":"/nav2/nav2-theta-star-planner-core-algorithm"},"next":{"text":"一张拓扑图如何变成可执行路线？逐函数拆解 Nav2 Route Server 的 241 个入口","link":"/nav2/nav2-route-241-functions-source-walkthrough"}},"headers":[],"relativePath":"nav2/teb-local-planner-core-algorithm.md","filePath":"nav2/teb-local-planner-core-algorithm.md","lastUpdated":null}'),r={name:"nav2/teb-local-planner-core-algorithm.md"};function h(_,e,b,u,m,g){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="路径会被障碍-拽弯-时间还会自己收缩-nav2-teb-图优化核心拆解" tabindex="-1">路径会被障碍“拽弯”，时间还会自己收缩：Nav2 TEB 图优化核心拆解 <a class="header-anchor" href="#路径会被障碍-拽弯-时间还会自己收缩-nav2-teb-图优化核心拆解" aria-label="Permalink to &quot;路径会被障碍“拽弯”，时间还会自己收缩：Nav2 TEB 图优化核心拆解&quot;">​</a></h1><p>一条普通路径只回答“经过哪里”，却没有回答“什么时候到这里”。没有时间，速度和加速度只能在路径生成后另算；空间绕障与时间可执行性也容易互相打架。</p><p>TEB 的做法更彻底：把未来轨迹写成一串二维位姿和时间间隔，让位置、朝向与时间一起成为优化变量。障碍物像斥力一样推开轨迹，目标时间不断拉短时间间隔，速度、加速度和底盘运动学又阻止轨迹收缩得过猛。最终结果不是某一条约束单独获胜，而是一张稀疏超图中所有误差共同妥协。</p><p>本文基于当前本地 <code>navigation2</code>、<code>teb_local_planner 0.9.1</code> 源码、测试与 <code>myworld_bringup</code> 现用参数，只拆 Timed Elastic Band、g2o 顶点与边、软约束、外内循环、障碍关联、可选同伦类和速度提取等核心算法。</p><p><img src="'+s+`" alt="TEB 核心算法总览"></p><h2 id="一、teb-优化的不是路径点-而是时空轨迹" tabindex="-1">一、TEB 优化的不是路径点，而是时空轨迹 <a class="header-anchor" href="#一、teb-优化的不是路径点-而是时空轨迹" aria-label="Permalink to &quot;一、TEB 优化的不是路径点，而是时空轨迹&quot;">​</a></h2><h3 id="_1-1-位姿顶点同时保存位置和朝向" tabindex="-1">1.1 位姿顶点同时保存位置和朝向 <a class="header-anchor" href="#_1-1-位姿顶点同时保存位置和朝向" aria-label="Permalink to &quot;1.1 位姿顶点同时保存位置和朝向&quot;">​</a></h3><p>第 <code>i</code> 个 <code>VertexPose</code> 保存：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s_i = (x_i, y_i, theta_i)</span></span></code></pre></div><p>位置决定轨迹形状，<code>theta_i</code> 决定机器人朝向。当前后的 Pose 一起变化时，速度、加速度、转弯和非完整运动学误差都会跟着变化。</p><h3 id="_1-2-时间顶点夹在相邻位姿之间" tabindex="-1">1.2 时间顶点夹在相邻位姿之间 <a class="header-anchor" href="#_1-2-时间顶点夹在相邻位姿之间" aria-label="Permalink to &quot;1.2 时间顶点夹在相邻位姿之间&quot;">​</a></h3><p>相邻 Pose 之间保存一个正数 <code>VertexTimeDiff</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ΔT_i &gt; 0</span></span></code></pre></div><p>若有 <code>N</code> 个 Pose，就有 <code>N-1</code> 个 TimeDiff。两类变量交替形成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pose_0 ─ ΔT_0 ─ Pose_1 ─ ΔT_1 ─ ... ─ Pose_N-1</span></span></code></pre></div><p>因此，TEB 能通过移动 Pose 改变空间路径，也能通过修改 <code>ΔT</code> 改变速度计划。</p><h3 id="_1-3-起点和终点是固定顶点" tabindex="-1">1.3 起点和终点是固定顶点 <a class="header-anchor" href="#_1-3-起点和终点是固定顶点" aria-label="Permalink to &quot;1.3 起点和终点是固定顶点&quot;">​</a></h3><p>轨迹初始化后，首尾 Pose 被设置为 fixed。g2o 不移动它们，只调整中间 Pose 和全部 TimeDiff。</p><p>起点固定保证命令从机器人当前状态出发；终点固定保证局部轨迹仍到达当前局部目标。软约束之间的妥协主要发生在中间自由度上。</p><h3 id="_1-4-全局路径只是初值和可选参考" tabindex="-1">1.4 全局路径只是初值和可选参考 <a class="header-anchor" href="#_1-4-全局路径只是初值和可选参考" aria-label="Permalink to &quot;1.4 全局路径只是初值和可选参考&quot;">​</a></h3><p>初次规划时，<code>initTrajectoryToGoal()</code> 从裁剪后的全局路径构造 Pose。每段初始时间取平移时间和转向时间的较大值：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ΔT_init = max(</span></span>
<span class="line"><span>  translation_distance / max_vel_x,</span></span>
<span class="line"><span>  abs(delta_yaw) / max_vel_theta</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>全局路径不是不可改变的硬轨道。若没有 Via Point 约束，中间 Pose 可以被障碍、时间和运动学边显著拉离初始路径。</p><h2 id="二、弹性带为什么会自动增删采样点" tabindex="-1">二、弹性带为什么会自动增删采样点 <a class="header-anchor" href="#二、弹性带为什么会自动增删采样点" aria-label="Permalink to &quot;二、弹性带为什么会自动增删采样点&quot;">​</a></h2><h3 id="_2-1-时间间隔过大就一分为二" tabindex="-1">2.1 时间间隔过大就一分为二 <a class="header-anchor" href="#_2-1-时间间隔过大就一分为二" aria-label="Permalink to &quot;2.1 时间间隔过大就一分为二&quot;">​</a></h3><p><code>autoResize()</code> 发现：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ΔT_i &gt; dt_ref + dt_hysteresis</span></span></code></pre></div><p>就把该时间间隔平分，在两个 Pose 的平均位置插入一个新 Pose，并增加一个同样大小的新 TimeDiff。</p><p>当前 <code>dt_ref=0.3 s</code>、<code>dt_hysteresis=0.1 s</code>，所以超过 <code>0.4 s</code> 的段会被继续细分。</p><h3 id="_2-2-时间间隔过小就合并相邻段" tabindex="-1">2.2 时间间隔过小就合并相邻段 <a class="header-anchor" href="#_2-2-时间间隔过小就合并相邻段" aria-label="Permalink to &quot;2.2 时间间隔过小就合并相邻段&quot;">​</a></h3><p>当：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ΔT_i &lt; dt_ref - dt_hysteresis</span></span></code></pre></div><p>且采样数高于最小值时，源码删除一个中间 Pose，把被删除段的时间加到相邻 TimeDiff。当前低于 <code>0.2 s</code> 的段可能触发合并。</p><p>这组上下阈值形成迟滞，避免采样点在 <code>0.3 s</code> 附近不断插入和删除。</p><h3 id="_2-3-动态障碍开关改变重采样深度" tabindex="-1">2.3 动态障碍开关改变重采样深度 <a class="header-anchor" href="#_2-3-动态障碍开关改变重采样深度" aria-label="Permalink to &quot;2.3 动态障碍开关改变重采样深度&quot;">​</a></h3><p><code>optimizeTEB()</code> 设置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fast_mode = !include_dynamic_obstacles</span></span></code></pre></div><p><code>fast_mode=true</code> 时，<code>autoResize()</code> 扫描一遍就退出；否则最多重复一百轮，直到不再修改。</p><p>当前 <code>myworld_bringup</code> 没有覆盖 <code>include_dynamic_obstacles</code>，因此沿用默认 <code>true</code>，会进入非快速重采样。但现有 Costmap 障碍都被构造成静态点，动态障碍边实际上没有可连接对象。</p><h3 id="_2-4-热启动只剪掉已经走过的前段" tabindex="-1">2.4 热启动只剪掉已经走过的前段 <a class="header-anchor" href="#_2-4-热启动只剪掉已经走过的前段" aria-label="Permalink to &quot;2.4 热启动只剪掉已经走过的前段&quot;">​</a></h3><p>新目标与旧终点距离、角度变化不大时，TEB 不重新建带。<code>updateAndPruneTEB()</code> 最多向前检查十个 Pose，寻找最接近新起点的位置，删除已经走过的中间 Pose，再用机器人新位姿覆盖固定起点。</p><p>这让上周期优化结果成为本周期初值，降低重复求解成本，也让轨迹随机器人前进持续向前滚动。</p><p><img src="`+n+'" alt="轨迹初始化、自动采样与热启动"></p><h2 id="三、一张-g2o-图里连接了哪些变量" tabindex="-1">三、一张 g2o 图里连接了哪些变量 <a class="header-anchor" href="#三、一张-g2o-图里连接了哪些变量" aria-label="Permalink to &quot;三、一张 g2o 图里连接了哪些变量&quot;">​</a></h2><h3 id="_3-1-pose-和-timediff-都进入优化器" tabindex="-1">3.1 Pose 和 TimeDiff 都进入优化器 <a class="header-anchor" href="#_3-1-pose-和-timediff-都进入优化器" aria-label="Permalink to &quot;3.1 Pose 和 TimeDiff 都进入优化器&quot;">​</a></h3><p><code>AddTEBVertices()</code> 按照 Pose、TimeDiff、Pose、TimeDiff 的顺序分配 g2o ID，并把 TEB 自己持有的顶点指针加入 <code>SparseOptimizer</code>。</p><p>图清理时，源码先断开顶点与边，再从优化器移除顶点，避免 g2o 把仍属于 TEB 的状态对象删除。</p><h3 id="_3-2-一元边约束单个变量" tabindex="-1">3.2 一元边约束单个变量 <a class="header-anchor" href="#_3-2-一元边约束单个变量" aria-label="Permalink to &quot;3.2 一元边约束单个变量&quot;">​</a></h3><p>典型一元边包括：</p><ul><li><code>EdgeTimeOptimal</code>：连接一个 TimeDiff，推动时间缩短。</li><li><code>EdgeObstacle</code>：连接一个 Pose，惩罚机器人模型离障碍过近。</li><li><code>EdgeInflatedObstacle</code>：同时表达最小安全距离和较缓的膨胀距离。</li><li><code>EdgeViaPoint</code>：把某个中间 Pose 拉向参考点。</li></ul><h3 id="_3-3-二元边约束相邻位姿" tabindex="-1">3.3 二元边约束相邻位姿 <a class="header-anchor" href="#_3-3-二元边约束相邻位姿" aria-label="Permalink to &quot;3.3 二元边约束相邻位姿&quot;">​</a></h3><p>典型二元边包括：</p><ul><li>差速非完整运动学边。</li><li>车式最小转弯半径边。</li><li>最短路径边。</li><li>偏好旋转方向边。</li></ul><p>它们只连接局部相邻状态，所以整张图保持稀疏。</p><h3 id="_3-4-多元边把空间与时间耦合起来" tabindex="-1">3.4 多元边把空间与时间耦合起来 <a class="header-anchor" href="#_3-4-多元边把空间与时间耦合起来" aria-label="Permalink to &quot;3.4 多元边把空间与时间耦合起来&quot;">​</a></h3><p>速度边连接两个 Pose 和一个 TimeDiff。加速度边连接三个 Pose 与两个 TimeDiff。起步／停车加速度边还把实测起始速度或目标速度作为参数带入。</p><p>这正是 TEB 的核心：如果某段距离不变而 <code>ΔT</code> 变小，速度误差会上升；若相邻两段速度变化过快，加速度误差也会上升。空间与时间不可能各自独立优化。</p><h3 id="_3-5-总目标是加权误差平方和" tabindex="-1">3.5 总目标是加权误差平方和 <a class="header-anchor" href="#_3-5-总目标是加权误差平方和" aria-label="Permalink to &quot;3.5 总目标是加权误差平方和&quot;">​</a></h3><p>每条 g2o 边计算误差向量 <code>e_k</code>，信息矩阵 <code>Ω_k</code> 保存对应权重。LM 求解器最小化：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>J = Σ e_kᵀ Ω_k e_k</span></span></code></pre></div><p>权重不是物理单位换算器，而是不同目标之间的谈判筹码。把某个权重调得极大，会让优化优先满足该误差，但也可能恶化数值条件或挤压其他目标。</p><p><img src="'+l+'" alt="TEB 的稀疏超图顶点与约束边"></p><h2 id="四、速度、加速度和时间如何互相制衡" tabindex="-1">四、速度、加速度和时间如何互相制衡 <a class="header-anchor" href="#四、速度、加速度和时间如何互相制衡" aria-label="Permalink to &quot;四、速度、加速度和时间如何互相制衡&quot;">​</a></h2><h3 id="_4-1-差速线速度来自位移与时间" tabindex="-1">4.1 差速线速度来自位移与时间 <a class="header-anchor" href="#_4-1-差速线速度来自位移与时间" aria-label="Permalink to &quot;4.1 差速线速度来自位移与时间&quot;">​</a></h3><p>相邻位姿位移为 <code>ΔS</code>，方向符号由位移在前一 Pose 朝向上的投影确定：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>v_i = signed_norm(ΔS) / ΔT_i</span></span>\n<span class="line"><span>omega_i = normalize(theta_i+1-theta_i) / ΔT_i</span></span></code></pre></div><p>当前 <code>exact_arc_length=false</code>，平移长度使用欧氏距离近似，不使用圆弧精确长度。</p><h3 id="_4-2-速度边只惩罚越界部分" tabindex="-1">4.2 速度边只惩罚越界部分 <a class="header-anchor" href="#_4-2-速度边只惩罚越界部分" aria-label="Permalink to &quot;4.2 速度边只惩罚越界部分&quot;">​</a></h3><p>差速速度误差使用区间惩罚：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-max_vel_x_backwards ≤ v_i ≤ max_vel_x</span></span>\n<span class="line"><span>abs(omega_i) ≤ max_vel_theta</span></span></code></pre></div><p>落在允许区间内时误差为零；越过边界后误差线性增加，再由 g2o 目标函数平方并乘权重。</p><p>当前限制为前进 <code>0.26 m/s</code>、后退 <code>0.05 m/s</code>、角速度 <code>1.0 rad/s</code>。</p><h3 id="_4-3-加速度边比较相邻两段速度" tabindex="-1">4.3 加速度边比较相邻两段速度 <a class="header-anchor" href="#_4-3-加速度边比较相邻两段速度" aria-label="Permalink to &quot;4.3 加速度边比较相邻两段速度&quot;">​</a></h3><p>中间 Pose 对应的线加速度近似为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a_i = 2 × (v_i+1-v_i) / (ΔT_i+ΔT_i+1)</span></span></code></pre></div><p>角加速度同理使用相邻角速度。当前上限为 <code>2.5 m/s²</code> 和 <code>3.2 rad/s²</code>。</p><p>起点边还把当前 Twist 与首段预测速度比较；目标速度默认不自由，因此末段会被拉向零速度。</p><h3 id="_4-4-时间最优边持续压缩每个-δt" tabindex="-1">4.4 时间最优边持续压缩每个 <code>ΔT</code> <a class="header-anchor" href="#_4-4-时间最优边持续压缩每个-δt" aria-label="Permalink to &quot;4.4 时间最优边持续压缩每个 `ΔT`&quot;">​</a></h3><p><code>EdgeTimeOptimal</code> 的误差就是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>e_time = ΔT_i</span></span></code></pre></div><p>进入 g2o 后贡献 <code>weight_optimaltime × ΔT_i²</code>。它不断推动总时间缩短，但速度和加速度边会在收缩过度时产生更大的反向代价。</p><h3 id="_4-5-当前没有单独启用最短路径边" tabindex="-1">4.5 当前没有单独启用最短路径边 <a class="header-anchor" href="#_4-5-当前没有单独启用最短路径边" aria-label="Permalink to &quot;4.5 当前没有单独启用最短路径边&quot;">​</a></h3><p><code>weight_shortest_path</code> 默认是零，<code>AddEdgesShortestPath()</code> 不会创建边。当前轨迹变短主要来自时间最优、障碍、运动学和初始几何的共同作用，不是显式最短路径项。</p><p><img src="'+c+`" alt="速度、加速度与时间最优的耦合"></p><h2 id="五、障碍如何把弹性带推开" tabindex="-1">五、障碍如何把弹性带推开 <a class="header-anchor" href="#五、障碍如何把弹性带推开" aria-label="Permalink to &quot;五、障碍如何把弹性带推开&quot;">​</a></h2><h3 id="_5-1-距离基于完整机器人模型" tabindex="-1">5.1 距离基于完整机器人模型 <a class="header-anchor" href="#_5-1-距离基于完整机器人模型" aria-label="Permalink to &quot;5.1 距离基于完整机器人模型&quot;">​</a></h3><p><code>EdgeObstacle</code> 不只计算 Pose 中心到障碍点的距离，而是调用当前机器人模型的 <code>calculateDistance()</code>。</p><p>现用 TEB 模型是半径 <code>0.22 m</code> 的圆。障碍误差因此按圆形机器人外缘到障碍的距离计算。</p><h3 id="_5-2-最小距离和膨胀距离是两层斥力" tabindex="-1">5.2 最小距离和膨胀距离是两层斥力 <a class="header-anchor" href="#_5-2-最小距离和膨胀距离是两层斥力" aria-label="Permalink to &quot;5.2 最小距离和膨胀距离是两层斥力&quot;">​</a></h3><p>当前：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>min_obstacle_dist = 0.25 m</span></span>
<span class="line"><span>inflation_dist = 0.45 m</span></span>
<span class="line"><span>weight_obstacle = 50.0</span></span>
<span class="line"><span>weight_inflation = 0.1</span></span></code></pre></div><p>进入 <code>0.25 m</code> 内产生高权重安全距离误差；进入 <code>0.45 m</code> 内还会产生较弱的线性膨胀误差。这让轨迹在碰到硬边界前就开始远离障碍。</p><h3 id="_5-3-新关联策略不会让每个-pose-连接全部障碍" tabindex="-1">5.3 新关联策略不会让每个 Pose 连接全部障碍 <a class="header-anchor" href="#_5-3-新关联策略不会让每个-pose-连接全部障碍" aria-label="Permalink to &quot;5.3 新关联策略不会让每个 Pose 连接全部障碍&quot;">​</a></h3><p><code>legacy_obstacle_association=false</code> 时，每个自由 Pose：</p><ul><li>强制包含距离小于 <code>min_obstacle_dist × force_inclusion_factor</code> 的障碍。</li><li>忽略距离大于 <code>min_obstacle_dist × cutoff_factor</code> 的障碍。</li><li>其余障碍只保留最近的左侧和右侧对象。</li></ul><p>这样把边数量从“Pose 数乘全部障碍数”压缩为局部相关集合。</p><h3 id="_5-4-当前左右侧判断存在坐标边界" tabindex="-1">5.4 当前左右侧判断存在坐标边界 <a class="header-anchor" href="#_5-4-当前左右侧判断存在坐标边界" aria-label="Permalink to &quot;5.4 当前左右侧判断存在坐标边界&quot;">​</a></h3><p>源码用 Pose 朝向向量与障碍质心的二维叉积判断左右，却没有先计算“障碍质心减 Pose 位置”的相对向量。</p><p>在地图原点远离机器人时，左右关联可能受绝对坐标影响。距离强制包含仍能抓住极近障碍，但普通左右筛选应通过偏移地图原点的回归场景验证。</p><h3 id="_5-5-costmap-点障碍不是动态障碍" tabindex="-1">5.5 Costmap 点障碍不是动态障碍 <a class="header-anchor" href="#_5-5-costmap-点障碍不是动态障碍" aria-label="Permalink to &quot;5.5 Costmap 点障碍不是动态障碍&quot;">​</a></h3><p>当前插件扫描 Costmap 的致命栅格并创建 <code>PointObstacle</code>。这些对象没有速度，<code>isDynamic()</code> 为假。</p><p>虽然默认 <code>include_dynamic_obstacles=true</code>，<code>AddEdgesDynamicObstacles()</code> 会跳过所有现有点障碍。配置中的 Costmap Converter 实现又在当前移植代码中被注释，因此不能把动态障碍权重理解成已经生效。</p><h2 id="六、差速运动学如何阻止横着滑" tabindex="-1">六、差速运动学如何阻止横着滑 <a class="header-anchor" href="#六、差速运动学如何阻止横着滑" aria-label="Permalink to &quot;六、差速运动学如何阻止横着滑&quot;">​</a></h2><h3 id="_6-1-非完整约束惩罚侧向位移" tabindex="-1">6.1 非完整约束惩罚侧向位移 <a class="header-anchor" href="#_6-1-非完整约束惩罚侧向位移" aria-label="Permalink to &quot;6.1 非完整约束惩罚侧向位移&quot;">​</a></h3><p>差速运动学边的核心误差为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>e_nh =</span></span>
<span class="line"><span>abs(</span></span>
<span class="line"><span>  (cos(theta_i)+cos(theta_i+1)) × Δy</span></span>
<span class="line"><span>  - (sin(theta_i)+sin(theta_i+1)) × Δx</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>当相邻位姿连线与平均朝向一致时，误差接近零；出现横向滑移时误差增大。</p><h3 id="_6-2-前进偏好惩罚倒车方向" tabindex="-1">6.2 前进偏好惩罚倒车方向 <a class="header-anchor" href="#_6-2-前进偏好惩罚倒车方向" aria-label="Permalink to &quot;6.2 前进偏好惩罚倒车方向&quot;">​</a></h3><p>另一个误差检查：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ΔS · heading_i</span></span></code></pre></div><p>投影为负时产生惩罚。当前 <code>weight_kinematics_forward_drive=1000</code>，所以优化强烈偏好前进；这不是禁止倒车，速度边仍允许最低 <code>-0.05 m/s</code>。</p><h3 id="_6-3-当前选择差速边而非车式边" tabindex="-1">6.3 当前选择差速边而非车式边 <a class="header-anchor" href="#_6-3-当前选择差速边而非车式边" aria-label="Permalink to &quot;6.3 当前选择差速边而非车式边&quot;">​</a></h3><p><code>buildGraph()</code> 在 <code>min_turning_radius=0</code> 时创建 <code>EdgeKinematicsDiffDrive</code>。只有最小转弯半径和对应权重都非零，才改用 <code>EdgeKinematicsCarlike</code>。</p><p>当前 <code>max_vel_y=0</code>、<code>min_turning_radius=0</code>，因此是差速模型：不允许横移，但允许原地转向，不约束汽车式最小转弯半径。</p><h2 id="七、四轮外循环如何逐步收紧障碍约束" tabindex="-1">七、四轮外循环如何逐步收紧障碍约束 <a class="header-anchor" href="#七、四轮外循环如何逐步收紧障碍约束" aria-label="Permalink to &quot;七、四轮外循环如何逐步收紧障碍约束&quot;">​</a></h2><h3 id="_7-1-外循环先调整轨迹分辨率" tabindex="-1">7.1 外循环先调整轨迹分辨率 <a class="header-anchor" href="#_7-1-外循环先调整轨迹分辨率" aria-label="Permalink to &quot;7.1 外循环先调整轨迹分辨率&quot;">​</a></h3><p>每轮先运行 <code>autoResize()</code>，让 TimeDiff 回到参考时间窗附近。顶点数量改变后，g2o 图必须重新构建。</p><h3 id="_7-2-构图后执行-lm-内循环" tabindex="-1">7.2 构图后执行 LM 内循环 <a class="header-anchor" href="#_7-2-构图后执行-lm-内循环" aria-label="Permalink to &quot;7.2 构图后执行 LM 内循环&quot;">​</a></h3><p><code>buildGraph()</code> 加入全部有效顶点和约束边，<code>optimizeGraph()</code> 初始化 g2o，再运行 Levenberg-Marquardt。</p><p>当前 <code>no_inner_iterations=5</code>、<code>no_outer_iterations=4</code>，一个控制周期最多执行四轮构图，每轮五次 LM 迭代。</p><h3 id="_7-3-每轮清图但保留优化后的-teb" tabindex="-1">7.3 每轮清图但保留优化后的 TEB <a class="header-anchor" href="#_7-3-每轮清图但保留优化后的-teb" aria-label="Permalink to &quot;7.3 每轮清图但保留优化后的 TEB&quot;">​</a></h3><p>求解后，Pose 和 TimeDiff 的估计值已经写回 TEB 顶点。<code>clearGraph()</code> 删除边和优化器索引，却保留这些状态，下一外循环继续以新结果构图。</p><h3 id="_7-4-障碍权重逐轮倍增" tabindex="-1">7.4 障碍权重逐轮倍增 <a class="header-anchor" href="#_7-4-障碍权重逐轮倍增" aria-label="Permalink to &quot;7.4 障碍权重逐轮倍增&quot;">​</a></h3><p>外循环初始 <code>weight_multiplier=1</code>，每轮乘默认 <code>weight_adapt_factor=2</code>。四轮构图的障碍主权重倍率依次为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1 → 2 → 4 → 8</span></span></code></pre></div><p>逐步加重障碍约束，比初始就设置极端大权重更有利于优化收敛。</p><p><img src="`+d+`" alt="TEB 外循环、构图与 LM 内循环"></p><h2 id="八、多同伦类别怎样避免困在单一路线" tabindex="-1">八、多同伦类别怎样避免困在单一路线 <a class="header-anchor" href="#八、多同伦类别怎样避免困在单一路线" aria-label="Permalink to &quot;八、多同伦类别怎样避免困在单一路线&quot;">​</a></h2><h3 id="_8-1-同伦类区分障碍左右绕行" tabindex="-1">8.1 同伦类区分障碍左右绕行 <a class="header-anchor" href="#_8-1-同伦类区分障碍左右绕行" aria-label="Permalink to &quot;8.1 同伦类区分障碍左右绕行&quot;">​</a></h3><p>两条路径若无法在不穿过障碍的前提下连续变形成彼此，就属于不同拓扑类别。<code>HomotopyClassPlanner</code> 用 H-Signature 把候选路径编码为复数或时空签名，签名接近的候选视为同一类。</p><h3 id="_8-2-图搜索生成不同绕行候选" tabindex="-1">8.2 图搜索生成不同绕行候选 <a class="header-anchor" href="#_8-2-图搜索生成不同绕行候选" aria-label="Permalink to &quot;8.2 图搜索生成不同绕行候选&quot;">​</a></h3><p>图搜索在障碍两侧放置关键点，连接不碰撞且大致朝向目标的边，再用深度优先搜索枚举起点到终点的简单路径。每个新等价类初始化一条独立 TEB。</p><h3 id="_8-3-候选可以并行优化" tabindex="-1">8.3 候选可以并行优化 <a class="header-anchor" href="#_8-3-候选可以并行优化" aria-label="Permalink to &quot;8.3 候选可以并行优化&quot;">​</a></h3><p>不同 TEB 没有共享优化变量，开启多线程时可分别执行完整的外内循环。候选成本由 g2o 边代价、可选总时间、障碍缩放和 Via Point 缩放组成。</p><h3 id="_8-4-选择器带有轨迹切换迟滞" tabindex="-1">8.4 选择器带有轨迹切换迟滞 <a class="header-anchor" href="#_8-4-选择器带有轨迹切换迟滞" aria-label="Permalink to &quot;8.4 选择器带有轨迹切换迟滞&quot;">​</a></h3><p>上一周期最佳轨迹的成本会乘 <code>selection_cost_hysteresis</code>，初始全局路径候选也可乘偏好系数。即使另一个候选短暂更优，<code>switching_blocking_period</code> 仍可阻止立即切换，减少控制振荡。</p><h3 id="_8-5-当前配置关闭这条分支" tabindex="-1">8.5 当前配置关闭这条分支 <a class="header-anchor" href="#_8-5-当前配置关闭这条分支" aria-label="Permalink to &quot;8.5 当前配置关闭这条分支&quot;">​</a></h3><p>当前 <code>myworld_bringup</code> 明确设置：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enable_homotopy_class_planning = false</span></span></code></pre></div><p>所以现用控制链只维护一个 <code>TebOptimalPlanner</code>。障碍两侧的替代路线不会被同时生成、分别优化再择优；单条 TEB 更省算力，但更依赖初值并可能落入局部最优。</p><h2 id="九、优化轨迹如何变成当前速度" tabindex="-1">九、优化轨迹如何变成当前速度 <a class="header-anchor" href="#九、优化轨迹如何变成当前速度" aria-label="Permalink to &quot;九、优化轨迹如何变成当前速度&quot;">​</a></h2><h3 id="_9-1-速度提取从轨迹起点向前看" tabindex="-1">9.1 速度提取从轨迹起点向前看 <a class="header-anchor" href="#_9-1-速度提取从轨迹起点向前看" aria-label="Permalink to &quot;9.1 速度提取从轨迹起点向前看&quot;">​</a></h3><p><code>getVelocityCommand()</code> 至少需要两个 Pose。它把 <code>look_ahead_poses</code> 限制在合法范围，并从开头累加 TimeDiff。</p><p>若累计时间达到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dt_ref × look_ahead_poses</span></span></code></pre></div><p>就提前停止，使用实际选中的前视 Pose。</p><h3 id="_9-2-差速命令由首尾状态差分得到" tabindex="-1">9.2 差速命令由首尾状态差分得到 <a class="header-anchor" href="#_9-2-差速命令由首尾状态差分得到" aria-label="Permalink to &quot;9.2 差速命令由首尾状态差分得到&quot;">​</a></h3><p>当前差速模式下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vx = sign(ΔS · heading_0) × norm(ΔS) / accumulated_dt</span></span>
<span class="line"><span>vy = 0</span></span>
<span class="line"><span>omega = normalize(theta_k-theta_0) / accumulated_dt</span></span></code></pre></div><p>这不是直接读取某个 g2o 顶点中的速度，因为速度从未作为独立顶点保存；它由优化后的 Pose 与 TimeDiff 推导。</p><h3 id="_9-3-软约束之后还有硬限幅" tabindex="-1">9.3 软约束之后还有硬限幅 <a class="header-anchor" href="#_9-3-软约束之后还有硬限幅" aria-label="Permalink to &quot;9.3 软约束之后还有硬限幅&quot;">​</a></h3><p>速度边只是优化软约束，有限迭代后仍可能轻微超限。插件外壳随后执行 <code>saturateVelocity()</code>，把最终 <code>vx</code>、<code>vy</code>、<code>omega</code> 限制到活动速度边界。</p><p>因此，图优化负责找到兼顾多目标的轨迹，硬限幅负责守住真正发布命令的最后边界。</p><p><img src="`+p+'" alt="同伦候选选择与速度命令提取"></p><h2 id="十、当前配置真正运行的算法画像" tabindex="-1">十、当前配置真正运行的算法画像 <a class="header-anchor" href="#十、当前配置真正运行的算法画像" aria-label="Permalink to &quot;十、当前配置真正运行的算法画像&quot;">​</a></h2><h3 id="_10-1-它是单轨迹差速-teb" tabindex="-1">10.1 它是单轨迹差速 TEB <a class="header-anchor" href="#_10-1-它是单轨迹差速-teb" aria-label="Permalink to &quot;10.1 它是单轨迹差速 TEB&quot;">​</a></h3><p><code>myworld_bringup</code> 默认选择 <code>TEB</code> 控制器，使用圆形机器人模型、差速运动学和单条 TEB，不启用同伦类候选。</p><h3 id="_10-2-它偏好前进而非绝对禁止倒车" tabindex="-1">10.2 它偏好前进而非绝对禁止倒车 <a class="header-anchor" href="#_10-2-它偏好前进而非绝对禁止倒车" aria-label="Permalink to &quot;10.2 它偏好前进而非绝对禁止倒车&quot;">​</a></h3><p>前进偏好权重为 <code>1000</code>，后退速度仍允许到 <code>0.05 m/s</code>。只有在其他代价足够大时，优化才可能接受低速倒车。</p><h3 id="_10-3-它以时间最优为主而非显式最短路" tabindex="-1">10.3 它以时间最优为主而非显式最短路 <a class="header-anchor" href="#_10-3-它以时间最优为主而非显式最短路" aria-label="Permalink to &quot;10.3 它以时间最优为主而非显式最短路&quot;">​</a></h3><p><code>weight_optimaltime=1</code>，<code>weight_shortest_path=0</code>。TEB 会压缩执行时间，同时由速度、加速度、障碍和运动学阻止不可执行的捷径。</p><h3 id="_10-4-它没有真正接通动态障碍预测" tabindex="-1">10.4 它没有真正接通动态障碍预测 <a class="header-anchor" href="#_10-4-它没有真正接通动态障碍预测" aria-label="Permalink to &quot;10.4 它没有真正接通动态障碍预测&quot;">​</a></h3><p>Costmap 提供的仍是静态点障碍；动态边没有数据对象。若要使用时空动态避障，必须先让障碍输入携带速度，而不是只打开参数。</p><h2 id="十一、最容易误解的算法边界" tabindex="-1">十一、最容易误解的算法边界 <a class="header-anchor" href="#十一、最容易误解的算法边界" aria-label="Permalink to &quot;十一、最容易误解的算法边界&quot;">​</a></h2><h3 id="_11-1-权重不是硬约束" tabindex="-1">11.1 权重不是硬约束 <a class="header-anchor" href="#_11-1-权重不是硬约束" aria-label="Permalink to &quot;11.1 权重不是硬约束&quot;">​</a></h3><p>障碍、速度、加速度与运动学首先都是优化误差。有限迭代可能留下残差，所以输出还需要碰撞可行性检查和速度硬限幅。</p><h3 id="_11-2-轨迹光滑不等于曲率连续" tabindex="-1">11.2 轨迹光滑不等于曲率连续 <a class="header-anchor" href="#_11-2-轨迹光滑不等于曲率连续" aria-label="Permalink to &quot;11.2 轨迹光滑不等于曲率连续&quot;">​</a></h3><p>TEB 优化离散 Pose 与时间差，没有直接构造连续曲率多项式。采样密度、运动学权重和局部几何共同决定视觉平滑度。</p><h3 id="_11-3-单条-teb-不会主动跨越拓扑障碍" tabindex="-1">11.3 单条 TEB 不会主动跨越拓扑障碍 <a class="header-anchor" href="#_11-3-单条-teb-不会主动跨越拓扑障碍" aria-label="Permalink to &quot;11.3 单条 TEB 不会主动跨越拓扑障碍&quot;">​</a></h3><p>局部优化擅长把当前初值拉到附近更优解，却不擅长穿过高代价障碍带去寻找另一侧路线。同伦类关闭后，这个局部最优属性更明显。</p><h3 id="_11-4-动态障碍参数不等于动态输入已存在" tabindex="-1">11.4 动态障碍参数不等于动态输入已存在 <a class="header-anchor" href="#_11-4-动态障碍参数不等于动态输入已存在" aria-label="Permalink to &quot;11.4 动态障碍参数不等于动态输入已存在&quot;">​</a></h3><p>算法边已经具备时间预测能力，但当前输入链只提供静态 Costmap 点。配置能力和真实数据流必须分开判断。</p><h3 id="_11-5-障碍关联值得做地图平移回归" tabindex="-1">11.5 障碍关联值得做地图平移回归 <a class="header-anchor" href="#_11-5-障碍关联值得做地图平移回归" aria-label="Permalink to &quot;11.5 障碍关联值得做地图平移回归&quot;">​</a></h3><p>现有左右判断使用绝对质心向量。把同一局部场景整体平移后，理论上规划结果应保持等价；若关联集合变化，就能直接暴露坐标原点依赖。</p><h2 id="十二、结语" tabindex="-1">十二、结语 <a class="header-anchor" href="#十二、结语" aria-label="Permalink to &quot;十二、结语&quot;">​</a></h2><p>TEB 的本质不是“让路径更圆滑”，而是把轨迹几何和执行时间放进同一个稀疏非线性最小二乘问题。</p><p>Pose 决定往哪里走，TimeDiff 决定多快走；障碍边把轨迹推开，时间边让轨迹收紧，速度和加速度边限制收紧速度，运动学边阻止底盘做出不可能的横移。外循环持续重采样并提高障碍权重，LM 内循环寻找这场多目标拉扯的局部平衡。</p><p>读懂这张图后，TEB 调参就不再是盲目堆权重：先确认状态变量和底盘模型，再确认哪些边真实存在，随后观察哪类误差主导优化，最后才决定增加约束、改变时间分辨率或启用多同伦候选。</p>',178)])])}const k=a(r,[["render",h]]);export{x as __pageData,k as default};
